def prime_length(s: str) -> bool:
    """Return True if the length of the string is a prime number, False otherwise."""
    n = len(s)
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
